Definition fh_res (c : pcore) : ecv * pcore :=
  let f := pc_f c in
  if Z.testbit f 11 && negb (Z.testbit f 4) then (EC_http_loc HE_BAD_TRANSFER_ENCODING LOC_FH_TE1, c)
  else if Z.testbit f 13 && negb (Z.testbit f 11) then (EC_http_loc HE_BAD_TRANSFER_ENCODING LOC_FH_TE2, c)
  else if Z.testbit f 0 then (EC_clear, pc_set_state c 11)
  else if Z.testbit f 10 then
    (if negb (pc_blim_has c =? 0) && (pc_blim c <? pc_len c) then (EC_http_loc HE_BODY_LIMIT LOC_FH_BODYLIM, c)
     else if pc_len c =? 0 then (EC_clear, pc_set_state c 11)
     else (EC_clear, pc_set_state_f c 3 (Z.lor f 8)))
  else if Z.testbit f 11 then (EC_clear, pc_set_state_f c 7 (Z.lor f 8))
  else (EC_clear, mkPC (pc_blim_has c) (pc_blim c) 0 0 (pc_skip c) (pc_hlim c) 11 f).

(* [comment removed for export] *)
Definition fh_assigns (c : pcore) : bool := negb (ec_cat (fst (fh_res c)) =? 0).

Lemma fh_res_ok : forall c, pcore_ok c -> pcore_ok (snd (fh_res c)).
Proof.
  intros c (Bh & Bl & Ln & Ln0 & Sk & Hl & Stt & Ff). pose proof (lor8_f14 _ Ff) as F8.
  unfold fh_res.
  repeat (lazymatch goal with |- context [if ?b then _ else _] => destruct b end); cbn; unfold pcore_ok; cbn;
    repeat (split; [first [fast_assumption | lia | cbn; qtauto] |]); first [fast_assumption | lia | cbn; qtauto].
Qed.

