Definition fh_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P E lo : Z) (c : pcore) (pad7 pad2 : list byte) (g : bool) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch (body_W lo sp P E) m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ rw_cells rsegs m' P (ParserCoreCells (snd (fh_res c)) pad7 pad2)
    /\ rw_cells rsegs m' E (ErrCodeCells (fst (fh_res c)))
    /\ HttpCat m' (fh_assigns c || g) /\ XStatics m'.

Definition fh_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P E lo : Z) (c : pcore) (pad7 pad2 ej : list byte) (g : bool),
  rw_cells rsegs m P (ParserCoreCells c pad7 pad2) -> pcore_ok c ->
  rw_cells rsegs m E [CB 24 ej] ->
  HttpCat m g -> XStatics m ->
  stk rsegs m lo (bv_unsigned sp) -> lo + 80 <= bv_unsigned sp -> 0xb4000 <= lo ->
  bv_unsigned sp <= P -> P + 80 <= 2^64 -> bv_unsigned sp <= E -> E + 24 <= 2^64 -> (P + 80 <= E \/ E + 24 <= P) ->
  mem_inv rsegs m ->
  evt rsegs (fh_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P E lo c pad7 pad2 g m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz P) (wz E) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_BP_FINISH_HEADER) fc None m (seg_rom rsegs)).

